    if (t === 'datetime') return { kind: 'datetime' };
    if (t === 'date')     return { kind: 'date' };
    if (t === 'number' || t === 'integer' || t === 'real' || t === 'float') return { kind: 'number', min: rawType.min, max: rawType.max, unit: rawType.unit, def: rawType['default'] };
    if (t === 'longtext' || t === 'textarea') return { kind: 'longtext' };
    if (t === 'text' || t === 'string') return { kind: 'text', unit: rawType.unit, def: rawType['default'] };
