, function (req, res) {\n  try {\n    var filename = _safeName(req.body && req.body.filename);\n    var ext = (filename.indexOf('.') >= 0 ? filename.split('.').pop() : '').toLowerCase();\n    var spec = UPLOAD_TYPES[ext];\n    if (!spec) return res.status(400).json({ message: 'Extension non autorisee. Types acceptes : ' + Object.keys(UPLOAD_TYPES).join(', ') });\n    var b64 = String((req.body && req.body.data_base64) || '');\n    var comma = b64.indexOf(',');\n    if (b64.slice(0, 5) === 'data:' && comma > 0) b64 = b64.slice(comma + 1); // tolere les data: URLs\n    if (b64.length === 0 || !/^[A-Za-z0-9+/=\\r\\n]+$/.test(b64)) return res.status(400).json({ message: 'Donnees base64 invalides' });\n    if (b64.length > Math.ceil(UPLOAD_MAX_BYTES / 3) * 4 + 16) return res.status(413).json({ message: 'Fichier trop volumineux (max 5 Mo)' });\n    var buf = Buffer.from(b64, 'base64');\n    if (!buf.length) return res.status(400).json({ message: 'Fichier vide' });\n    if (buf.length > UPLOAD_MAX_BYTES) return res.status(413).json({ message: 'Fichier trop volumineux (max 5 Mo)' });\n    if (!_magicOk(buf, spec.magic)) return res.status(400).json({ message: 'Le contenu ne correspond pas a l extension (signature invalide)' });\n    var info = db.prepare('INSERT INTO uploads (user_id, filename, mimetype, size, data) VALUES (?, ?, ?, ?, ?)').run(req.user.sub, filename, spec.mime, buf.length, buf);\n    _audit(req, 'upload.create', 'uploads', info.lastInsertRowid); res.status(201).json({ id: info.lastInsertRowid, filename: filename, mimetype: spec.mime, size: buf.length });\n  } catch (e) { console.error('[POST /api/uploads]', e.message); res.status(500).json({ message: 'Erreur interne' }); }\n});\n\n// GET /api/uploads -- lister ses fichiers (metadonnees seules, jamais le BLOB)\napp.get('/api/uploads', authMiddleware, function (req, res) {\n  try { res.json(db.prepare('SELECT id, filename, mimetype, size, created_at FROM uploads WHERE user_id = ? ORDER BY id DESC').all(req.user.sub)); }\n  catch (e) { console.error('[GET /api/uploads]', e.message); res.status(500).json({ message: 'Erreur interne' }); }\n});\n\n// GET /api/uploads/:id -- servir un fichier (scope proprietaire, en-tetes surs anti-XSS/anti-sniff)\napp.get('/api/uploads/:id', authMiddleware, function (req, res) {\n  try {\n    var id = parseInt(req.params.id, 10);\n    if (isNaN(id)) return res.status(400).json({ message: 'Identifiant invalide' });\n    var row = db.prepare('SELECT filename, mimetype, size, data FROM uploads WHERE id = ? AND user_id = ?').get(id, req.user.sub);\n    if (!row) return res.status(404).json({ message: 'Introuvable' });\n    // Content-Type = valeur validee stockee (jamais l entree brute) ; nosniff empeche le MIME-sniffing ;\n    // CSP sandbox + default-src none neutralise toute execution si le fichier est ouvert directement.\n    res.setHeader('Content-Type', row.mimetype);\n    res.setHeader('X-Content-Type-Options', 'nosniff');\n    res.setHeader('Content-Disposition', 'inline; filename=\"' + row.filename.replace(/[^A-Za-z0-9._-]/g, '_') + '\"');\n    res.setHeader('Content-Security-Policy', \"default-src 'none'; sandbox\");\n    res.setHeader('Cache-Control', 'private, no-store');\n    res.setHeader('Content-Length', String(row.size));\n    res.end(row.data);\n  } catch (e) { console.error('[GET /api/uploads/:id]', e.message); res.status(500).json({ message: 'Erreur interne' }); }\n});\n\n// DELETE /api/uploads/:id -- suppression scopee proprietaire (anti-IDOR)\napp.delete('/api/uploads/:id', authMiddleware, function (req, res) {\n  try {\n    var id = parseInt(req.params.id, 10);\n    if (isNaN(id)) return res.status(400).json({ message: 'Identifiant invalide' });\n    var info = db.prepare('DELETE FROM uploads WHERE id = ? AND user_id = ?').run(id, req.user.sub);\n    if (!info.changes) return res.status(404).json({ message: 'Introuvable' });\n    _audit(req, 'upload.delete', 'uploads', id);\n    res.json({ deleted: id });\n  } catch (e) {