        lines.push("  const over = await B.agent.post('/" + sn + "').send({ " + cBody.filter(function (x) { return x.indexOf("'" + s.capacity.field + "'") !== 0; }).concat(["'" + p.field + "': par.body.id", "'" + s.capacity.field + "': " + (function () { var cl = classifyField(s.capacity.field, cfg.fields[s.capacity.field]); return cl.max != null ? cl.max : 1000000; })()]).join(', ') + " });");
        lines.push("  assert.strictEqual(over.status, 409, 'dépasser la capacité restante doit être refusé');");
