    lines.push("  assert.strictEqual(r.status, 403);");
    lines.push("});");
  })();
  lines.push("");
  lines.push("test('audit : les échecs de connexion sont journalisés', async () => {");
  lines.push("  await request(app).post('/api/login').send({ username: 'inconnu_' + rnd(), password: 'zzz' });");
  lines.push("  const db = require('../db');");
  lines.push("  const n = db.prepare(\"SELECT COUNT(*) AS n FROM audit_log WHERE action = 'auth.login.failed'\").get().n;");
  lines.push("  assert.ok(n >= 1, 'au moins un échec de connexion doit être journalisé');");
  lines.push("});");
  // Tier 2 : verrouillage de compte, revocation de session, changement de mot de passe
  lines.push("");
  lines.push("test('Tier2 verrouillage : 5 echecs -> compte verrouille (429)', async () => {");
  lines.push("  const u = await mkUser();");
