  lines.push("  const r = await request(app).post('/api/login').send({ username: u.username, password: u.password });");
  lines.push("  assert.strictEqual(r.status, 429, 'le compte doit etre verrouille apres 5 echecs (recu ' + r.status + ')');");
  lines.push("});");
  lines.push("");
  lines.push("test('Tier2 revocation : apres logout, l ancienne session est invalide (401)', async () => {");
  lines.push("  const u = await mkUser();");
  lines.push("  assert.strictEqual((await u.agent.get('/api/me')).status, 200);");
  lines.push("  await u.agent.post('/api/logout');");
  lines.push("  assert.strictEqual((await u.agent.get('/api/me')).status, 401, 'la session doit etre revoquee au logout');");
  lines.push("});");
  lines.push("");
